CREATE TEMP TABLE s503c_cards (id bigint, s_ed text, s_book text, src_ch int, src_vn int, src_text text, t_ed text, tgt_book text, tgt_ch int, tgt_vn int, old_note text, new_note text, thread_id bigint, old_mnote text, new_mnote text) ON COMMIT DROP;
INSERT INTO s503c_cards VALUES
(5383,'canon','mark',16,16,$n$He that believes and is baptized shall be saved; but he that believes not shall be damned.$n$,'canon','john',10,27,$n$thread:my-sheep-hear-my-voice-hearing-reveals-not-creates | *The believing that saves is the hearing-that-reveals.* The believing reveals the prior election; it does not create it.$n$,$n$John 10:27 — *My sheep hear my voice, and I know them, and they follow me:* *He that believes and is baptized shall be saved; but he that believes not shall be damned.* (Mark 16:16) Believing and being baptized is how the saved are seen, not how they are made. Yahusha (Jesus) says what the believing is: a sheep hearing and following. He says *I know them* in the same breath, so the knowing comes first. The one who believes not is the one who was never his sheep.$n$,680,$n$*The believing that saves is the hearing-that-reveals.* The believing reveals the prior election; it does not create it.$n$,$n$John 10:27 — *My sheep hear my voice, and I know them, and they follow me.* The sheep hear because they are known, so the believing in Mark shows a sheep and does not make one.$n$),
(5384,'canon','mark',16,16,$n$He that believes and is baptized shall be saved; but he that believes not shall be damned.$n$,'canon','romans',8,29,$n$thread:my-sheep-hear-my-voice-hearing-reveals-not-creates | Romans 8:29-30's foreknown-predestined-called-justified-glorified chain.$n$,$n$Romans 8:29 — *For whom he did foreknow, he also did predestinate to be conformed to the image of his Son, that he might be the firstborn among many brethren.* *He that believes and is baptized shall be saved; but he that believes not shall be damned.* (Mark 16:16) Mark says the one who believes is saved. Paul says who he was before he believed: *foreknow*. Elohim (God) knew them ahead and set them to be like his Son, who is firstborn of many brethren. The believing is the sheep showing what was already settled.$n$,680,$n$Romans 8:29-30's foreknown-predestined-called-justified-glorified chain.$n$,$n$Romans 8:29 — *For whom he did foreknow, he also did predestinate.* Being known ahead comes first, and the believing that follows only shows who was known.$n$),
(5385,'canon','mark',16,16,$n$He that believes and is baptized shall be saved; but he that believes not shall be damned.$n$,'canon','1-peter',1,2,$n$thread:my-sheep-hear-my-voice-hearing-reveals-not-creates | 1 Peter 1:2's *elect according to the foreknowledge of Elohim the Father*.$n$,$n$1 Peter 1:2 — *Elect according to the foreknowledge of Elohim (God) the Father, through sanctification of the Spirit, unto obedience and sprinkling of the blood of Yahusha HaMashiach (Jesus Christ): Grace unto you, and peace, be multiplied.* *He that believes and is baptized shall be saved; but he that believes not shall be damned.* (Mark 16:16) Peter writes to the strangers scattered through Pontus and the rest, and he calls them chosen before they did a thing. Believing and baptism come after a choice already held in the Father's knowledge. The scattered are the elect, and their obeying shows it.$n$,680,$n$1 Peter 1:2's *elect according to the foreknowledge of Elohim the Father*.$n$,$n$1 Peter 1:2 — *Elect according to the foreknowledge of Elohim (God) the Father.* The scattered are chosen by the Father's foreknowledge, so their believing shows a choice already made.$n$),
(5386,'canon','mark',16,16,$n$He that believes and is baptized shall be saved; but he that believes not shall be damned.$n$,'canon','revelation',13,8,$n$thread:my-sheep-hear-my-voice-hearing-reveals-not-creates | Revelation 13:8's names-written-before-the-foundation.$n$,$n$Revelation 13:8 — *And all that dwell upon the earth shall worship him, whose names are not written in the book of life of the Lamb slain from the foundation of the world.* *He that believes and is baptized shall be saved; but he that believes not shall be damned.* (Mark 16:16) The ones who do not believe are the ones whose names were never written. John sees the book kept *from the foundation of the world*. Believing does not write a name in it. The names stood there before anyone was born, and the hearing only brings them to light.$n$,680,$n$Revelation 13:8's names-written-before-the-foundation.$n$,$n$Revelation 13:8 — *whose names are not written in the book of life of the Lamb slain from the foundation of the world.* Names are written or not written from before the world, so hearing shows which names were there.$n$),
(7013,'canon','luke',7,50,$n$And he said to the woman, Your faith has saved you; go in peace.$n$,'canon','john',10,27,$n$thread:my-sheep-hear-my-voice-hearing-reveals-not-creates | *Thy faith hath saved thee; go in peace.* The first of four Lukan *thy faith hath saved/made-thee-whole* verdicts (Luke 7:50; 8:48; 17:19; 18:42). The faith that saves is the response of the sheep who hears the shepherd's voice — hearing reveals what the Father had already placed.$n$,$n$John 10:27 — *My sheep hear my voice, and I know them, and they follow me:* *And he said to the woman, Your faith has saved you; go in peace.* (Luke 7:50) She came to his feet in a house and heard him, and he tells her it was her faith that saved her. Her faith was a sheep hearing its shepherd. He knew her, and she followed. The faith did not make her his. It showed she was.$n$,680,$n$*Thy faith hath saved thee; go in peace.* The first of four Lukan *thy faith hath saved/made-thee-whole* verdicts (Luke 7:50; 8:48; 17:19; 18:42). The faith that saves is the response of the sheep who hears the shepherd's voice — hearing reveals what the Father had already placed.$n$,$n$John 10:27 — *My sheep hear my voice, and I know them, and they follow me.* Her faith is the hearing of a sheep that was already known, so it shows what she was.$n$),
(7016,'canon','luke',8,8,$n$And other fell on good ground, and sprang up, and bare fruit an hundredfold. And when he had said these things, he cried, He that has ears to hear, let him hear.$n$,'canon','john',10,27,$n$thread:my-sheep-hear-my-voice-hearing-reveals-not-creates | *He that hath ears to hear, let him hear.* The same hearing-architecture Yochanan (John) 10:27 names — the sheep hear and turn, the hearing reveals what the Father had placed.$n$,$n$John 10:27 — *My sheep hear my voice, and I know them, and they follow me:* *And other fell on good ground, and sprang up, and bare fruit an hundredfold. And when he had said these things, he cried, He that has ears to hear, let him hear.* (Luke 8:8) Good ground bore fruit a hundredfold, and he cries out for ears to hear. The ground was good before the seed fell. The sheep hear his voice because they are his, and what they bear shows what they were all along.$n$,680,$n$*He that hath ears to hear, let him hear.* The same hearing-architecture Yochanan (John) 10:27 names — the sheep hear and turn, the hearing reveals what the Father had placed.$n$,$n$John 10:27 — *My sheep hear my voice, and I know them.* The ears that hear are the sheep he knows, so the hearing shows them and does not make them.$n$),
(7020,'canon','luke',8,48,$n$And he said unto her, Daughter, be of good comfort: your faith has made you whole; go in peace.$n$,'canon','john',10,27,$n$thread:my-sheep-hear-my-voice-hearing-reveals-not-creates | *Daughter, thy faith hath made thee whole; go in peace.* The second of four Lukan *thy faith hath saved/made-thee-whole* verdicts. The hearing reveals what the Father had placed; the *daughter* address names her in the seed-of-promise.$n$,$n$John 10:27 — *My sheep hear my voice, and I know them, and they follow me:* *And he said unto her, Daughter, be of good comfort: your faith has made you whole; go in peace.* (Luke 8:48) He calls her *Daughter* before he says a word about healing. She is his own, one of the scattered of the house of Yashar'el (Israel). Her faith that reached for him was her hearing, and his knowing her stands first in his words: *I know them*.$n$,680,$n$*Daughter, thy faith hath made thee whole; go in peace.* The second of four Lukan *thy faith hath saved/made-thee-whole* verdicts. The hearing reveals what the Father had placed; the *daughter* address names her in the seed-of-promise.$n$,$n$John 10:27 — *My sheep hear my voice, and I know them, and they follow me.* He names her his own, and her faith is the hearing of a sheep he already knew.$n$),
(7032,'canon','luke',9,57,$n$And it came to pass, that, as they went in the way, a certain man said unto him, Lord, I will follow you whithersoever you go.$n$,'canon','john',10,27,$n$thread:my-sheep-hear-my-voice-hearing-reveals-not-creates | The would-be-disciples sayings — *Lord, suffer me first to go and bury my father* (Luke 9:59); *Lord, I will follow thee; but let me first go bid them farewell* (Luke 9:61) — name the cause-and-effect-of-hearing diagnostic: the sheep hear and turn, the half-hearted-hearing fails under the test of the cost.$n$,$n$John 10:27 — *My sheep hear my voice, and I know them, and they follow me:* *And it came to pass, that, as they went in the way, a certain man said unto him, Lord, I will follow you whithersoever you go.* (Luke 9:57) A man says he will follow wherever Yahusha (Jesus) goes. Saying it is not the following he means. The sheep follow because they hear and are known. A man's promise to follow does not make a sheep, and the shepherd does not take it for one.$n$,680,$n$The would-be-disciples sayings — *Lord, suffer me first to go and bury my father* (Luke 9:59); *Lord, I will follow thee; but let me first go bid them farewell* (Luke 9:61) — name the cause-and-effect-of-hearing diagnostic: the sheep hear and turn, the half-hearted-hearing fails under the test of the cost.$n$,$n$John 10:27 — *My sheep hear my voice, and I know them, and they follow me.* The following he names comes from hearing and being known, not from a man's promise to follow.$n$),
(7040,'canon','luke',11,27,$n$And it came to pass, as he spake these things, a certain woman of the company lifted up her voice, and said unto him, Blessed is the womb that bare you, and the paps which you have sucked.$n$,'canon','john',10,27,$n$thread:my-sheep-hear-my-voice-hearing-reveals-not-creates | *Yea rather, blessed are they that hear the word of Elohim (God), and keep it.* Luke alone carries the woman's blessing-of-the-womb and the King's correction — the blessedness is not by physical-lineage to him as a son-of-Adam by birth, but by hearing-and-keeping the Word.$n$,$n$John 10:27 — *My sheep hear my voice, and I know them, and they follow me:* *And it came to pass, as he spake these things, a certain woman of the company lifted up her voice, and said unto him, Blessed is the womb that bare you, and the paps which you have sucked.* (Luke 11:27) A woman calls the womb that bore him blessed. Praising where he came from is not hearing his voice. He turns it to the ones who hear. The sheep are the ones who hear and are known, and the blessing is theirs.$n$,680,$n$*Yea rather, blessed are they that hear the word of Elohim (God), and keep it.* Luke alone carries the woman's blessing-of-the-womb and the King's correction — the blessedness is not by physical-lineage to him as a son-of-Adam by birth, but by hearing-and-keeping the Word.$n$,$n$John 10:27 — *My sheep hear my voice, and I know them.* The blessing is for the ones who hear him and are known, not for praising where he came from.$n$),
(7060,'canon','luke',15,4,$n$What man of you, having an hundred sheep, if he lose one of them, does not leave the ninety and nine in the wilderness, and go after that which is lost, until he find it?$n$,'canon','john',10,27,$n$thread:my-sheep-hear-my-voice-hearing-reveals-not-creates | The lost-sheep parable's shepherd-finds-the-sheep cause-and-effect carries the same hearing-reveals-not-creates architecture the framework names. The sheep does not become-a-sheep by being-found; the sheep was-a-sheep before it wandered, IS-a-sheep when it is lost, and IS-found because the shepherd-knows-his-own.$n$,$n$John 10:27 — *My sheep hear my voice, and I know them, and they follow me:* *What man of you, having an hundred sheep, if he lose one of them, does not leave the ninety and nine in the wilderness, and go after that which is lost, until he find it?* (Luke 15:4) A man leaves the ninety and nine to go after the one that is lost, because it is his. The sheep was a sheep before it wandered and still a sheep while lost. He finds it because it is his own. Hearing does not make a sheep. It finds one.$n$,680,$n$The lost-sheep parable's shepherd-finds-the-sheep cause-and-effect carries the same hearing-reveals-not-creates architecture the framework names. The sheep does not become-a-sheep by being-found; the sheep was-a-sheep before it wandered, IS-a-sheep when it is lost, and IS-found because the shepherd-knows-his-own.$n$,$n$John 10:27 — *My sheep hear my voice, and I know them, and they follow me.* The lost sheep is found because it was his all along, which is the order of knowing before following.$n$),
(7073,'canon','luke',17,19,$n$And he said unto him, Arise, go your way: your faith has made you whole.$n$,'canon','john',10,27,$n$thread:my-sheep-hear-my-voice-hearing-reveals-not-creates | *Arise, go thy way: thy faith hath made thee whole.* The third of four Lukan *thy faith hath saved/made-thee-whole* verdicts. The Samaritan returning to thank — the response of the sheep who hears the shepherd's voice.$n$,$n$John 10:27 — *My sheep hear my voice, and I know them, and they follow me:* *And he said unto him, Arise, go your way: your faith has made you whole.* (Luke 17:19) One of ten comes back, and Yahusha (Jesus) tells him to rise and go, because his faith has made him whole. The coming back is a sheep hearing the voice and following it. The faith shows whose he was. It does not make him so.$n$,680,$n$*Arise, go thy way: thy faith hath made thee whole.* The third of four Lukan *thy faith hath saved/made-thee-whole* verdicts. The Samaritan returning to thank — the response of the sheep who hears the shepherd's voice.$n$,$n$John 10:27 — *My sheep hear my voice, and I know them, and they follow me.* His coming back is the following of a sheep that hears, so the faith shows whose he was.$n$),
(7086,'canon','luke',18,42,$n$And Yahusha (Jesus) said unto him, Receive your sight: your faith has saved you.$n$,'canon','john',10,27,$n$thread:my-sheep-hear-my-voice-hearing-reveals-not-creates | *Receive thy sight: thy faith hath saved thee.* The fourth of four Lukan *thy faith hath saved/made-thee-whole* verdicts. The blind man at Yericho (Jericho) hearing the King's voice — the sheep hearing the shepherd.$n$,$n$John 10:27 — *My sheep hear my voice, and I know them, and they follow me:* *And Yahusha (Jesus) said unto him, Receive your sight: your faith has saved you.* (Luke 18:42) The blind man cried out to him on the road, and Yahusha (Jesus) says his faith has saved him. He could not see the shepherd, but he heard him and called. That is a sheep hearing. He knew the voice, and the faith shows it was his to know.$n$,680,$n$*Receive thy sight: thy faith hath saved thee.* The fourth of four Lukan *thy faith hath saved/made-thee-whole* verdicts. The blind man at Yericho (Jericho) hearing the King's voice — the sheep hearing the shepherd.$n$,$n$John 10:27 — *My sheep hear my voice, and I know them, and they follow me.* A blind man knowing the voice is a sheep hearing its shepherd, and the faith shows what he was.$n$),
(8076,'canon','john',6,37,$n$All that the Father gives me shall come to me; and him that comes to me I will in no wise cast out.$n$,'canon','jeremiah',31,10,$n$thread:my-sheep-hear-my-voice-hearing-reveals-not-creates | *All that the Father giveth me shall come to me* — *He that scattered Yashar'el (Israel) will gather him, and keep him, as a shepherd doth his flock.* The gathering is the Father's act; the Son receives those the Father gives.$n$,$n$Jeremiah 31:10 — *Hear the word of Yahuah (LORD), O ye nations, and declare it in the isles afar off, and say, He that scattered Yashar'el (Israel) will gather him, and keep him, as a shepherd doth his flock.* *All that the Father gives me shall come to me; and him that comes to me I will in no wise cast out.* (John 6:37) All the Father gives will come, and none who comes is cast out. Jeremiah says whose work it is: the one who scattered Yashar'el (Israel) gathers him and keeps him as a shepherd. The word is told in the isles afar off, and the ones who come are the ones he scattered.$n$,680,$n$*All that the Father giveth me shall come to me* — *He that scattered Yashar'el (Israel) will gather him, and keep him, as a shepherd doth his flock.* The gathering is the Father's act; the Son receives those the Father gives.$n$,$n$Jeremiah 31:10 — *He that scattered Yashar'el (Israel) will gather him, and keep him, as a shepherd doth his flock.* The gathering is the work of the one who scattered, so those who come are the ones the Father gives.$n$),
(8075,'canon','john',6,44,$n$No man can come to me, except the Father which has sent me draw him: and I will raise him up at the last day.$n$,'canon','hosea',11,4,$n$thread:my-sheep-hear-my-voice-hearing-reveals-not-creates | *No man can come to me, except the Father which hath sent me draw him* — *I drew them with cords of a man, with bands of love.* The drawing is the Father's; the response in time is the revealing of the drawing.$n$,$n$Hosea 11:4 — *I drew them with cords of a man, with bands of love: and I was to them as they that take off the yoke on their jaws, and I laid meat unto them.* *No man can come to me, except the Father which has sent me draw him: and I will raise him up at the last day.* (John 6:44) No one comes unless the Father draws him, and Hosea shows the drawing is old. Yahuah (LORD) drew Ephraim with cords and *bands of love* before they knew it. The coming in time is the drawing seen, not the drawing begun.$n$,680,$n$*No man can come to me, except the Father which hath sent me draw him* — *I drew them with cords of a man, with bands of love.* The drawing is the Father's; the response in time is the revealing of the drawing.$n$,$n$Hosea 11:4 — *I drew them with cords of a man, with bands of love.* The drawing comes first and is the Father's, so the coming only shows it.$n$),
(8074,'canon','john',6,65,$n$And he said, Therefore said I unto you, that no man can come unto me, except it were given unto him of my Father.$n$,'canon','ezekiel',36,26,$n$thread:my-sheep-hear-my-voice-hearing-reveals-not-creates | *Therefore said I unto you, that no man can come unto me, except it were given unto him of my Father* — the coming requires the new heart. The new heart is given of the Father. The Spirit who is put within causes the walking in statutes; the same Spirit causes the hearing of the shepherd's voice.$n$,$n$Ezekiel 36:26 — *A new heart also will I give you, and a new spirit will I put within you: and I will take away the stony heart out of your flesh, and I will give you an heart of flesh.* *And he said, Therefore said I unto you, that no man can come unto me, except it were given unto him of my Father.* (John 6:65) No one comes unless it is given him of the Father, and Ezekiel says what is given: *a new heart*, the stony one taken out and one of flesh put in. He says it to the house gathered out of all countries into their own land. The giving is his, and the hearing follows it.$n$,680,$n$*Therefore said I unto you, that no man can come unto me, except it were given unto him of my Father* — the coming requires the new heart. The new heart is given of the Father. The Spirit who is put within causes the walking in statutes; the same Spirit causes the hearing of the shepherd's voice.$n$,$n$Ezekiel 36:26 — *A new heart also will I give you, and a new spirit will I put within you.* What lets a sheep come is given by the Father to the gathered house, before any hearing.$n$),
(8081,'canon','john',10,26,$n$But you believe not, because you are not of my sheep, as I said unto you.$n$,'canon','revelation',13,8,$n$thread:my-sheep-hear-my-voice-hearing-reveals-not-creates | *Ye believe not, because ye are not of my sheep* — the names were written from the foundation of the world; those whose names are not written cannot hear when the shepherd calls. The hearing reveals what the foundation-of-the-world enrollment already settled.$n$,$n$Revelation 13:8 — *And all that dwell upon the earth shall worship him, whose names are not written in the book of life of the Lamb slain from the foundation of the world.* *But you believe not, because you are not of my sheep, as I said unto you.* (John 10:26) He says they do not believe because they are not his sheep, and John sees the same order in the book. Names are written or not written *from the foundation of the world*. Not believing took no name out. The names were there or not there from the start.$n$,680,$n$*Ye believe not, because ye are not of my sheep* — the names were written from the foundation of the world; those whose names are not written cannot hear when the shepherd calls. The hearing reveals what the foundation-of-the-world enrollment already settled.$n$,$n$Revelation 13:8 — *whose names are not written in the book of life of the Lamb slain from the foundation of the world.* The names were settled from the foundation, so not believing shows a name was never written.$n$),
(8080,'canon','john',10,27,$n$My sheep hear my voice, and I know them, and they follow me:$n$,'canon','jeremiah',31,3,$n$thread:my-sheep-hear-my-voice-hearing-reveals-not-creates | *I have loved thee with an everlasting love: therefore with lovingkindness have I drawn thee* — the drawing precedes the coming. The everlasting-love is the *gave them me* of John 10:29 spoken in the prophet's voice.$n$,$n$Jeremiah 31:3 — *Yahuah (LORD) hath appeared of old unto me, saying, Yea, I have loved thee with an everlasting love: therefore with lovingkindness have I drawn thee.* *My sheep hear my voice, and I know them, and they follow me:* (John 10:27) The sheep hear because they are known, and Jeremiah says how long they have been known. Yahuah (LORD) appeared of old and said it was *an everlasting love* that drew Yashar'el (Israel). The following in time answers a love that was there before.$n$,680,$n$*I have loved thee with an everlasting love: therefore with lovingkindness have I drawn thee* — the drawing precedes the coming. The everlasting-love is the *gave them me* of John 10:29 spoken in the prophet's voice.$n$,$n$Jeremiah 31:3 — *I have loved thee with an everlasting love: therefore with lovingkindness have I drawn thee.* The drawing by an everlasting love comes before the hearing, so the following answers an old love.$n$),
(8079,'canon','john',10,27,$n$My sheep hear my voice, and I know them, and they follow me:$n$,'canon','ezekiel',34,11,$n$thread:my-sheep-hear-my-voice-hearing-reveals-not-creates | *I, even I, will both search my sheep, and seek them out* — the shepherd's voice the sheep hear is the same shepherd Yechezkel (Ezekiel) names as the one who goes out searching.$n$,$n$Ezekiel 34:11 — *For thus saith Adonai Yahuah (the Lord GOD); Behold, I, even I, will both search my sheep, and seek them out.* *My sheep hear my voice, and I know them, and they follow me:* (John 10:27) The voice the sheep hear belongs to the shepherd Ezekiel heard say he would search for them himself. He does not send word and wait for the flock to find him. He seeks them out, scattered as they are, and they know the voice because they are his.$n$,680,$n$*I, even I, will both search my sheep, and seek them out* — the shepherd's voice the sheep hear is the same shepherd Yechezkel (Ezekiel) names as the one who goes out searching.$n$,$n$Ezekiel 34:11 — *Behold, I, even I, will both search my sheep, and seek them out.* The shepherd who calls is the one who goes out and finds his own scattered sheep himself.$n$),
(8073,'canon','john',10,27,$n$My sheep hear my voice, and I know them, and they follow me:$n$,'canon','matthew',13,11,$n$thread:my-sheep-hear-my-voice-hearing-reveals-not-creates | *Unto you it is given to know the mysteries of the kingdom of heaven, but to them it is not given* — the same cause-and-effect structure spoken in the parables-context. The hearing is given to the sheep.$n$,$n$Matthew 13:11 — *He answered and said unto them, Because it is given unto you to know the mysteries of the kingdom of heaven, but to them it is not given.* *My sheep hear my voice, and I know them, and they follow me:* (John 10:27) Why do some hear and some do not? He answers that it is *given*. The hearing is not earned and not chosen into. It is given to the ones who are his, and to the others it is not given. This is the sheep hearing his voice, said another way.$n$,680,$n$*Unto you it is given to know the mysteries of the kingdom of heaven, but to them it is not given* — the same cause-and-effect structure spoken in the parables-context. The hearing is given to the sheep.$n$,$n$Matthew 13:11 — *Because it is given unto you to know the mysteries of the kingdom of heaven.* Hearing the mysteries is given to some and not to others, so hearing shows who was given.$n$),
(8078,'canon','john',10,28,$n$And I give unto them eternal life; and they shall never perish, neither shall any man pluck them out of my hand.$n$,'canon','isaiah',49,15,$n$thread:my-sheep-hear-my-voice-hearing-reveals-not-creates | *Can a woman forget her sucking child, that she should not have compassion on the son of her womb? yea, they may forget, yet will I not forget thee* — the security of the sheep in the Father's hand named in Yeshayahu's (Isaiah's) gathering-prophecy register.$n$,$n$Isaiah 49:15 — *Can a woman forget her sucking child, that she should not have compassion on the son of her womb? yea, they may forget, yet will I not forget thee.* *And I give unto them eternal life; and they shall never perish, neither shall any man pluck them out of my hand.* (John 10:28) No one plucks them out of his hand, and Isaiah gives the reason. Zion said she was forgotten, and he answers that a mother may forget but he will not. The hand that holds them is the hand that does not forget, so they are kept.$n$,680,$n$*Can a woman forget her sucking child, that she should not have compassion on the son of her womb? yea, they may forget, yet will I not forget thee* — the security of the sheep in the Father's hand named in Yeshayahu's (Isaiah's) gathering-prophecy register.$n$,$n$Isaiah 49:15 — *yea, they may forget, yet will I not forget thee.* The one who will not forget Zion is the one whose hand keeps the sheep safe.$n$),
(8077,'canon','john',10,29,$n$My Father, which gave them me, is greater than all; and no man is able to pluck them out of my Father’s hand.$n$,'canon','deuteronomy',7,7,$n$thread:my-sheep-hear-my-voice-hearing-reveals-not-creates | *Yahuah (the LORD) did not set his love upon you, nor choose you, because ye were more in number than any people; for ye were the fewest of all people: But because Yahuah (the LORD) loved you* — the love-not-the-merit. The Father's *gave them me* sits on the same gratuitous-love substance.$n$,$n$Deuteronomy 7:7 — *Yahuah (LORD) did not set his love upon you, nor choose you, because ye were more in number than any people; for ye were the fewest of all people:* *My Father, which gave them me, is greater than all; and no man is able to pluck them out of my Father’s hand.* (John 10:29) The Father gave them, and Moses says why anyone is given. It was not for numbers or worth. Yahuah (LORD) set his love on the *fewest of all people* and kept the oath to their fathers. The giving was never earned by hearing. The hearing comes because the gift was made.$n$,680,$n$*Yahuah (the LORD) did not set his love upon you, nor choose you, because ye were more in number than any people; for ye were the fewest of all people: But because Yahuah (the LORD) loved you* — the love-not-the-merit. The Father's *gave them me* sits on the same gratuitous-love substance.$n$,$n$Deuteronomy 7:7 — *Yahuah (LORD) did not set his love upon you, nor choose you, because ye were more in number than any people.* The people were chosen by love and not by merit, which is the ground of the Father giving them.$n$),
(8072,'canon','john',17,9,$n$I pray for them: I pray not for the world, but for them which you have given me; for they are yours.$n$,'canon','revelation',17,8,$n$thread:my-sheep-hear-my-voice-hearing-reveals-not-creates | *I pray for them: I pray not for the world, but for them which thou hast given me; for they are thine* — *whose names were not written in the book of life from the foundation of the world.* The two categories are the same two categories: those given by the Father from the foundation, and those not. The praying is for the first; the world the praying is not for is the second.$n$,$n$Revelation 17:8 — *The beast that thou sawest was, and is not; and shall ascend out of the bottomless pit, and go into perdition: and they that dwell on the earth shall wonder, whose names were not written in the book of life from the foundation of the world, when they behold the beast that was, and is not, and yet is.* *I pray for them: I pray not for the world, but for them which you have given me; for they are yours.* (John 17:9) He prays for the ones given him and does not pray for the world. John saw the same line drawn in the book: names written, and names *not written* from the foundation. Those who wonder after the beast are outside it. The ones he prays for were his before he asked.$n$,680,$n$*I pray for them: I pray not for the world, but for them which thou hast given me; for they are thine* — *whose names were not written in the book of life from the foundation of the world.* The two categories are the same two categories: those given by the Father from the foundation, and those not. The praying is for the first; the world the praying is not for is the second.$n$,$n$Revelation 17:8 — *whose names were not written in the book of life from the foundation of the world.* The same two groups stand in the book from the foundation: those given to him, and those whose names were not written.$n$);
CREATE TEMP TABLE s503c_thread (id bigint, slug text, old_title text, new_title text, old_summary text, new_summary text) ON COMMIT DROP;
INSERT INTO s503c_thread VALUES (680, 'my-sheep-hear-my-voice-hearing-reveals-not-creates', $n$My sheep hear my voice — hearing reveals what was true before the foundation$n$, $n$My sheep hear my voice — hearing shows what a sheep already was (Ezekiel 34; John 10; John 8; Jeremiah 31; Revelation 13)$n$, $n$The good shepherd discourse contains a sentence the inherited reading cannot hold without rewriting it. *Ye believe not, because ye are not of my sheep.* The cause-and-effect is reversed from the gospel the modern pulpit preaches. The pulpit teaches *if you believe, you become a sheep.* The discourse teaches *if you are a sheep, you hear and believe.* The hearing is the revealing; the sheep-status is what is being revealed. The status precedes the response.

*But ye believe not, because ye are not of my sheep, as I said unto you. My sheep hear my voice, and I know them, and they follow me: and I give unto them eternal life; and they shall never perish, neither shall any man pluck them out of my hand. My Father, which gave them me, is greater than all; and no man is able to pluck them out of my Father's hand.* (John 10:26-29)

*Yahuah (the LORD) hath appeared of old unto me, saying, Yea, I have loved thee with an everlasting love: therefore with lovingkindness have I drawn thee.* (Jeremiah 31:3)

*And all that dwell upon the earth shall worship him, whose names are not written in the book of life of the Lamb slain from the foundation of the world.* (Revelation 13:8)

The Father gave them to the Son. The Father gave them before the foundation of the world. Their names were written then. The hearing of the shepherd's voice in time is the revealing of what was already true in the Father's foreknowledge — not the moment in which the sheep-status was created by the act of believing. The gathering of the scattered seed is not the recruitment of volunteers from the categorical nations; it is the homecoming of those whose names were written in the Lamb's book from the foundation.

This is why the gathering can be proclaimed broadly without the proclamation collapsing into a categorical invitation to all flesh. The proclamation goes out wherever the Father sends. Those who hear are revealed by their hearing to be sheep. Those who reject have the dust shaken off the foot, and the pearls are not cast before swine. The shepherd does not chase what was never his.$n$, $n$It ain't new. The shepherd who says his sheep hear his voice is the shepherd Ezekiel heard say he would go and find them himself:

*For thus saith Adonai Yahuah (the Lord GOD); Behold, I, even I, will both search my sheep, and seek them out.* (Ezekiel 34:11)

*As a shepherd seeketh out his flock in the day that he is among his sheep that are scattered; so will I seek out my sheep, and will deliver them out of all places where they have been scattered in the cloudy and dark day.* (Ezekiel 34:12)

Then the sentence the pulpit has to turn around to keep its gospel:

*But ye believe not, because ye are not of my sheep, as I said unto you.* (John 10:26)

*My sheep hear my voice, and I know them, and they follow me:* (John 10:27)

*And I give unto them eternal life; and they shall never perish, neither shall any man pluck them out of my hand.* (John 10:28)

*My Father, which gave them me, is greater than all; and no man is able to pluck them out of my Father’s hand.* (John 10:29)

Read the order. He does not say they are not his sheep because they do not believe. He says they do not believe because they are not his sheep. The pulpit preaches that believing makes a sheep. The shepherd says a sheep hears, and the hearing shows what it was. He says the same thing in the same gospel more than once:

*He that is of Elohim (God) heareth Elohim's (God’s) words: ye therefore hear them not, because ye are not of Elohim (God).* (John 8:47)

*And he said, Therefore said I unto you, that no man can come unto me, except it were given unto him of my Father.* (John 6:65)

*He answered and said unto them, Because it is given unto you to know the mysteries of the kingdom of heaven, but to them it is not given.* (Matthew 13:11)

The Father gave them, and the giving is old:

*Yahuah (LORD) hath appeared of old unto me, saying, Yea, I have loved thee with an everlasting love: therefore with lovingkindness have I drawn thee.* (Jeremiah 31:3)

*For whom he did foreknow, he also did predestinate to be conformed to the image of his Son, that he might be the firstborn among many brethren.* (Romans 8:29)

*And all that dwell upon the earth shall worship him, whose names are not written in the book of life of the Lamb slain from the foundation of the world.* (Revelation 13:8)

The names were written before the world was laid. The hearing comes in time and shows which names are there. So when Yahusha (Jesus) says to a woman in a house, or to a blind man on the road, that her faith or his faith has saved them, the faith is a sheep hearing:

*And he said to the woman, Thy faith hath saved thee; go in peace.* (Luke 7:50)

*And Yahusha (Jesus) said unto him, Receive thy sight: thy faith hath saved thee.* (Luke 18:42)

And the other sheep are not another kind:

*And other sheep I have, which are not of this fold: them also I must bring, and they shall hear my voice; and there shall be one fold, and one shepherd.* (John 10:16)

Those are the scattered of the house, out in the places Ezekiel named, and they will hear because they are his. This is why the good news is told everywhere and chased nowhere. The word goes out wherever the Father sends it, the sheep in the crowd hear, and the ones who will not hear are left where they stand:

*And whosoever shall not receive you, nor hear your words, when ye depart out of that house or city, shake off the dust of your feet.* (Matthew 10:14)

*Give not that which is holy unto the dogs, neither cast ye your pearls before swine, lest they trample them under their feet, and turn again and rend you.* (Matthew 7:6)

The shepherd goes after the one that is lost because it is his:

*What man of you, having an hundred sheep, if he lose one of them, doth not leave the ninety and nine in the wilderness, and go after that which is lost, until he find it?* (Luke 15:4)

He does not go after what was never his. Hearing does not make a sheep. It finds one.$n$);

DO $s503c$
DECLARE r record; x record; n int;
BEGIN
  FOR r IN SELECT * FROM s503c_cards LOOP
    SELECT xr.id, xr.note, sv.text AS stext, se.slug AS sed, sb.slug AS sbook, sc.chapter_number AS sch, sv.verse_number AS svn, te.slug AS ted, tb.slug AS tbook, tc.chapter_number AS tch, tv.verse_number AS tvn
      INTO x FROM cross_references xr
      JOIN verses sv ON sv.id = xr.source_verse_id JOIN chapters sc ON sc.id = sv.chapter_id JOIN books sb ON sb.id = sc.book_id JOIN editions se ON se.id = sb.edition_id
      JOIN verses tv ON tv.id = xr.target_verse_id JOIN chapters tc ON tc.id = tv.chapter_id JOIN books tb ON tb.id = tc.book_id JOIN editions te ON te.id = tb.edition_id
      WHERE xr.id = r.id;
    IF NOT FOUND THEN RAISE EXCEPTION 'S503c: card % is gone', r.id; END IF;
    IF x.sed <> r.s_ed OR x.sbook <> r.s_book OR x.sch <> r.src_ch OR x.svn <> r.src_vn OR x.ted <> r.t_ed OR x.tbook <> r.tgt_book OR x.tch <> r.tgt_ch OR x.tvn <> r.tgt_vn THEN
      RAISE EXCEPTION 'S503c: card % no longer sits on the verse pair this was written for', r.id; END IF;
    IF x.stext <> r.src_text THEN RAISE EXCEPTION 'S503c: live text of % %:% differs from the read-back — re-dump and rebuild', r.s_book, r.src_ch, r.src_vn; END IF;
    IF x.note IS DISTINCT FROM r.old_note AND x.note IS DISTINCT FROM r.new_note THEN RAISE EXCEPTION 'S503c: the live note of card % differs from the read-back — re-dump and rebuild', r.id; END IF;
    SELECT count(*) INTO n FROM cross_reference_thread_members m WHERE m.cross_reference_id = r.id AND m.thread_id = r.thread_id AND (m.member_note IS NOT DISTINCT FROM r.old_mnote OR m.member_note IS NOT DISTINCT FROM r.new_mnote);
    IF n <> 1 THEN RAISE EXCEPTION 'S503c: card % has no member row in thread % carrying the member note this was written against', r.id, r.thread_id; END IF;
  END LOOP;
  SELECT t.* INTO x FROM cross_reference_threads t JOIN s503c_thread s ON s.id = t.id AND s.slug = t.slug;
  IF NOT FOUND THEN RAISE EXCEPTION 'S503c: thread 680 not found under its slug'; END IF;
  SELECT count(*) INTO n FROM cross_reference_threads t JOIN s503c_thread s ON s.id = t.id
    WHERE (t.title = s.old_title AND t.summary_md = s.old_summary) OR (t.title = s.new_title AND t.summary_md = s.new_summary);
  IF n <> 1 THEN RAISE EXCEPTION 'S503c: thread 680 title/summary differ from the read-back — re-dump and rebuild'; END IF;
END $s503c$;

DO $s503c2$
DECLARE n_notes int; n_m int; n_t int; n_c int;
BEGIN
  SELECT count(*) INTO n_c FROM s503c_cards;
  UPDATE cross_references xr SET note = c.new_note FROM s503c_cards c WHERE xr.id = c.id AND xr.note IS NOT DISTINCT FROM c.old_note AND c.old_note IS DISTINCT FROM c.new_note;
  GET DIAGNOSTICS n_notes = ROW_COUNT;
  UPDATE cross_reference_thread_members m SET member_note = c.new_mnote FROM s503c_cards c WHERE m.cross_reference_id = c.id AND m.thread_id = c.thread_id AND m.member_note IS NOT DISTINCT FROM c.old_mnote AND c.old_mnote IS DISTINCT FROM c.new_mnote;
  GET DIAGNOSTICS n_m = ROW_COUNT;
  UPDATE cross_reference_threads t SET title = s.new_title, summary_md = s.new_summary FROM s503c_thread s WHERE t.id = s.id AND t.title = s.old_title AND t.summary_md = s.old_summary AND (s.old_title <> s.new_title OR s.old_summary <> s.new_summary);
  GET DIAGNOSTICS n_t = ROW_COUNT;
  RAISE NOTICE 'S503c (my-sheep-hear-my) summary: notes rewritten % / already there %; member notes rewritten % / already there %; thread rewritten % / already there %', n_notes, n_c - n_notes, n_m, n_c - n_m, n_t, 1 - n_t;
END $s503c2$;
COMMIT;
\echo 'session503c — my-sheep-hear-my done.'
